const app=document.querySelector('#app');let screen='lobby',role='法师',rank=7,rerolls=2,evolved=false,message='',ready=true;const names=['法师','战士','道士'];const skills={法师:'火球术',战士:'半月弯刀',道士:'灵魂火符'};const skillsNew={法师:'爆裂火球',战士:'环月刀阵',道士:'灵符阵'};const primary=()=>evolved?skillsNew[role]:skills[role];const btn=(text,action,cls='')=>`<button class="${cls}" data-action="${action}">${text}</button>`;function nav(){return `<nav class="review" aria-label="原型页面切换">${[['lobby','开局'],['battle','战斗'],['upgrade','升级'],['evolution','进化'],['build','构筑'],['result','结算']].map(([id,t])=>btn(t,'view:'+id,screen===id?'active':'')).join('')}</nav>`}function slots(){return `<div class="slots" aria-label="主动技能">${[primary(),'雷电','火墙','护盾','抗拒','空槽'].map((s,i)=>`<div class="slot">${s}<small>${i===0?(evolved?'进化':rank+'/8'):i===5?'—':(5-i)+'/8'}</small></div>`).join('')}</div>`}function render(){window.scrollTo(0,0);let html='';if(screen==='lobby'){html=`<div class="scene"></div><section class="content"><div class="row"><b>玛法幸存者</b><span class="pill">连续生存</span></div><div class="hero"><h1>重返比奇<br>独战千军</h1><p>活过二十分钟，炼成你的绝技。</p></div><div class="tabs" aria-label="职业">${names.map(n=>btn(n,'role:'+n,role===n?'active':'')).join('')}</div><div class="portrait">${role.slice(0,1)}</div><h2>${role} · ${skills[role]}</h2><p>${role==='法师'?'远程弹幕，连锁清场。':role==='战士'?'移动挥刀，近身破阵。':'符毒牵制，神兽同行。'}</p><div class="rule row"><div><b>比奇荒野</b><p>首个关卡 · 20 分钟</p></div><span>存活即通关</span></div>${btn('踏入荒野','start','primary')}<p class="footer">单指拖动移动 · 自动攻击 · 升级时暂停<br>首轮完整流程以法师为例，其他职业仅预览定位。</p></section>`}if(screen==='battle'){html=`<div class="scene"></div><div class="hud"><div class="row"><b>Lv.24</b><span>经验 63%</span>${btn('暂停','pause','pause')}</div><div class="xp"><i></i></div><div class="row"><span>比奇荒野</span><b class="clock">06:24</b><span>/ 20:00</span></div>${slots()}<div class="row" style="margin-top:8px"><span class="pill">被动 4 / 6 · 火焰戒指已持有</span>${btn('构筑','view:build','subtle')}</div></div><div class="field"><div class="hp" aria-label="生命76%"><i></i></div></div><div class="tip">${message||'拖动摇杆体验操作位置 · 场景为冻结实机画面'}</div><div class="controls"><div class="stick" role="img" aria-label="虚拟摇杆位置示意"><i></i></div><div class="actions">${btn('血瓶 2 / 3','potion')}${btn('演示升级','view:upgrade')}</div></div>`}if(screen==='upgrade'){html=`<section class="sheet"><div class="row"><h2>选择一次成长</h2><span>战斗已暂停</span></div><p>Lv.24 → 25 · 每次选择一项</p>${message?`<div class="toast" role="status">${message}</div>`:''}<button class="choice" data-action="choose:skill"><span>主力技能 · ${rank<8?'升级':'已满级'} · ${skills[role]}</span><strong>${rank<8?`Lv.${rank} → Lv.${rank+1}`:'转为额外强化'}</strong><p>${rank<8?'基础伤害 +25%，弹速 +15%。':'演示已到8级，请查看进化。'}</p><span>8级＋火焰戒指 → 寻找进化宝箱</span></button><button class="choice" data-action="choose:passive"><span>被动 · 2 → 3级</span><strong>疾风项链</strong><p>冷却缩减 10% → 15%</p><span>影响全部适用技能</span></button><button class="choice" data-action="choose:new"><span>新技能 · 占用最后一个空槽</span><strong>冰咆哮</strong><p>在敌群中制造冰霜爆发。</p><span>范围清怪 · 1 / 8级</span></button><div class="grid bottom">${btn('重掷 · 剩余 '+rerolls,'reroll')}${btn('返回战场','view:battle')}</div><p class="footer">原型演示选择反馈；不进行真实数值结算。</p></section>`}if(screen==='evolution'){html=`<section class="sheet"><div class="row"><h2>进化宝箱</h2>${btn('关闭','view:battle','subtle')}</div><div class="evolution"><div class="sigil">${role==='战士'?'斩':role==='道士'?'符':'炎'}</div><p>${skills[role]} →</p><h1>${skillsNew[role]}</h1><p>命中后爆裂，贯穿前方敌阵。</p></div><div class="rule"><div class="row"><span>基础技能</span><b>${ready?'8 / 8':'7 / 8'}</b></div><div class="row"><span>进化配件</span><b>火焰戒指 · 已持有</b></div><div class="row"><span>宝箱资格</span><b>第6分钟精英 · 合格</b></div></div>${ready?btn(evolved?'已获得 · 返回战场':'领悟进化','evolve','primary'):'<p class="toast">还差1级。先升级主技能，再来开启。</p>'+btn('返回战场','view:battle','primary')}<div class="bottom">${btn(ready?'检查条件不足状态':'检查条件满足状态','toggleReady','subtle')}</div></section>`}if(screen==='build'){html=`<section class="sheet"><div class="row"><h2>本局构筑</h2>${btn('返回','view:battle','subtle')}</div><p>优先培养两个主力，再补生存与控制。</p><div class="list"><h3>主动技能 · 5 / 6</h3>${[primary()+' · '+(evolved?'已进化':rank+'/8'),'雷电术 · 4/8','火墙 · 3/8','魔法盾 · 2/8','抗拒火环 · 1/8','空槽 · 可学习新技能'].map(s=>`<div class="row"><span>${s}</span><span class="pill">${s.startsWith(primary())?'主力':''}</span></div>`).join('')}<h3>被动构筑 · 4 / 6</h3><p>火焰戒指 1/5 · 疾风项链 2/5<br>长生手镯 2/5 · 拾取护符 1/5</p><h3>下一次进化</h3><p>${skills[role]} 8级＋火焰戒指＋合格宝箱</p><div class="bar"><i style="width:${rank/8*100}%"></i></div><p class="pill">${evolved?'已完成':rank<8?'还差1级主技能':'条件已齐，寻找宝箱'}</p></div>${btn('预览进化宝箱','view:evolution','primary bottom')}<p class="footer">外观：木剑／基础布衣。原型数值为演示。</p></section>`}if(screen==='result'){html=`<section class="sheet"><h1>荒野生还</h1><p>比奇荒野 · ${role} · 演示结算</p><div class="rule row"><h2>20:00</h2><b>存活通关</b></div><div class="list"><div class="row"><span>击败怪物</span><b>3,842</b></div><div class="row"><span>角色等级</span><b>Lv.68</b></div><div class="row"><span>完成进化</span><b>2 项</b></div></div><h3>本局主力</h3><p>${skillsNew[role]} · 伤害贡献 58%</p><div class="bar"><i style="width:58%"></i></div><p>雷霆连锁 · 伤害贡献 29%</p><div class="bar"><i style="width:29%"></i></div><div class="rule bottom"><b>下一局目标</b><p>尝试第二种职业，寻找不同进化组合。</p></div>${btn('再来一局','start','primary')}${btn('返回开局','view:lobby','subtle bottom')}<p class="footer">以上战绩为演示数据，不保存、不发放奖励。</p></section>`}app.innerHTML=`<div class="phone"><div class="notice">手机 UI 原型 · 演示数据 · 尚非可玩关卡</div>${html}${nav()}</div>`;app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));const stick=app.querySelector('.stick');if(stick){stick.onpointerdown=e=>{stick.setPointerCapture(e.pointerId);stick.querySelector('i').style.transform='translate(12px,-8px)'};stick.onpointerup=()=>stick.querySelector('i').style.transform='';}}function act(a){message='';if(a.startsWith('view:'))screen=a.split(':')[1];else if(a.startsWith('role:'))role=a.split(':')[1];else if(a==='start'){role='法师';screen='battle';rank=7;evolved=false;rerolls=2;}else if(a==='pause'){screen='build'}else if(a==='potion'){message='演示：使用血瓶，生命得到恢复。'}else if(a==='reroll'){if(rerolls>0){rerolls--;message='已重掷：当前原型展示固定示例选项。'}else message='本局重掷次数已用完。'}else if(a.startsWith('choose:')){if(a==='choose:skill')rank=Math.min(8,rank+1);screen='battle';message=a==='choose:skill'?'主技能已升级，进化条件即将齐备。':'已选择强化（演示反馈）。'}else if(a==='toggleReady')ready=!ready;else if(a==='evolve'){evolved=true;rank=8;screen='battle';message='进化完成：'+primary();}render()}render();
